css:
.m1-art{--bg:#f6f5f1;--ink:#1d1d1b;--ink2:#5c5b57;--line:#dcd9d0;--acc:#b0842f;--card:#fff;--hl:#fbf1dc;--warn:#b3261e}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .m1-art{--bg:#16171a;--ink:#ecebe7;--ink2:#a4a29c;--line:#34363b;--acc:#d6a54a;--card:#1f2125;--hl:#3a3220;--warn:#f2b8b5}}
:root[data-theme="dark"] .m1-art{--bg:#16171a;--ink:#ecebe7;--ink2:#a4a29c;--line:#34363b;--acc:#d6a54a;--card:#1f2125;--hl:#3a3220;--warn:#f2b8b5}
.m1-art{color:var(--ink);font:15px/1.7 system-ui,-apple-system,"Noto Sans TC",sans-serif}
.m1-art{max-width:1080px}
.m1-art h1{font-size:22px;margin:0 0 4px}
.m1-art h2{font-size:17px;margin:0 0 8px}
.m1-art h3{font-size:15px;margin:12px 0 6px}
.m1-art .m1-m{color:var(--ink2);font-size:13px;margin:0 0 14px}
.m1-art section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin-bottom:14px}
.m1-art .m1-rumor{border-color:var(--warn)}
.m1-art .m1-tag{display:inline-block;border:1px solid var(--warn);color:var(--warn);border-radius:4px;padding:0 6px;font-size:13px;font-weight:700}
.m1-art .m1-k{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin:8px 0}
.m1-art .m1-k div{border:1px solid var(--line);border-radius:8px;padding:8px 10px}
.m1-art .m1-k b{display:block;font-size:20px}
.m1-art .m1-k span{color:var(--ink2);font-size:12px}
.m1-art .m1-x{overflow-x:auto;-webkit-overflow-scrolling:touch}
.m1-art .m1-t{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}
.m1-art .m1-t th,.m1-art .m1-t td{border-bottom:1px solid var(--line);padding:4px 6px;text-align:right;white-space:nowrap}
.m1-art .m1-t th:first-child,.m1-art .m1-t td:first-child,.m1-art .m1-t td.m1-w{text-align:left}
.m1-art .m1-t td.m1-w{white-space:normal;min-width:260px}
.m1-art .m1-hl td{background:var(--hl);font-weight:700}
.m1-art .m1-s{color:var(--ink2);font-size:12px}
.m1-art a{color:var(--acc)}
.m1-art ul{padding-left:20px;margin:6px 0}
.m1-art li{margin:3px 0}
.m1-art .m1-evs{display:none}
.m1-art .m1-ev{border:1px solid var(--line);border-radius:8px;padding:8px 10px;margin:8px 0}
.m1-art .m1-ev p{margin:4px 0}
.m1-art .m1-ev dl{display:grid;grid-template-columns:auto 1fr;gap:2px 10px;margin:4px 0 0;font-size:13px;font-variant-numeric:tabular-nums}
.m1-art .m1-ev dt{color:var(--ink2)}
.m1-art .m1-ev dd{margin:0}
@media (max-width:640px){.m1-art .m1-evs{display:block}
.m1-art .m1-evt{display:none}}
.m1-art .m1-foot{color:var(--ink2);font-size:13px;text-align:center;margin-top:18px}
